(function(){var cover=document.querySelector(".app-opening"),app=document.getElementById("app"),observer,timer;function done(){cover?.remove();observer?.disconnect();clearTimeout(timer)}function check(){if(app?.childElementCount)requestAnimationFrame(done)}observer=new MutationObserver(check);if(app)observer.observe(app,{childList:true});timer=setTimeout(done,8000);check();window.addEventListener("pageshow",function(e){if(e.persisted)done()});})();
